# Generated by scripts/update-homebrew.py. Edit scripts/aigc.rb.in instead.
class Aigc < Formula
  desc "Local garbage collector for development storage on macOS"
  homepage "https://github.com/MyhreS/AI-Garbage-Collector"
  version "0.1.0"
  license "MIT"

  depends_on macos: :ventura

  on_macos do
    on_arm do
      url "https://github.com/MyhreS/AI-Garbage-Collector/releases/download/v0.1.0/aigc-aarch64-apple-darwin.tar.gz"
      sha256 "5a58c523e7e19d37c0987573563cb50637d3683f082e04233450650a0e4429a0"
    end

    on_intel do
      url "https://github.com/MyhreS/AI-Garbage-Collector/releases/download/v0.1.0/aigc-x86_64-apple-darwin.tar.gz"
      sha256 "6629d6b339585879daddd45ca147486545e3330ae13a0027ec351ebe5aca09a3"
    end
  end

  def install
    bin.install "aigc"
    doc.install "README.md"
  end

  service do
    name macos: "io.aigc.collector"
    run [opt_bin/"aigc", "collect"]
    run_type :interval
    interval 3600
    run_at_load true
    working_dir Dir.home
    environment_variables HOME: Dir.home,
                          PATH: "#{Dir.home}/.local/bin:#{Dir.home}/.docker/bin:/usr/local/bin:#{std_service_path_env}"
  end

  def caveats
    <<~EOS
      Installation does not start cleanup. Enable the hourly collector with:
        brew services start myhres/aigc/aigc

      Inspect resources with:
        aigc status

      If switching from the standalone installer, stop its service first:
        aigc service uninstall
      Then use brew services to manage the collector. Do not use sudo.
    EOS
  end
end
